ec33SX27scripts00C1?~~~~~~~~~~~~~~~".
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S. Import LbA_NLoops.NDig.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Section Back.
  Context {HCEIL : HeapCeil}.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Variables (R : bvmap 5 word) (M : mem) (sp ds fl lo shi FR : Z).
  Variables (padra opret dpretpc : Z) (fillw : word) (SVop : list word) (sv9 sv18 sv19 sv20 sv21 sv22 sv23 : word).
  Hypothesis HFR : FR = 80 \/ FR = 96.
  Hypothesis VAR : (padra = PADRA_UL /\ dpretpc = DPU_RETPC) \/ (padra = PADRA_L /\ dpretpc = DPL_RETPC).
  Hypothesis Hopret : 0 <= opret < 2 ^ 64.
  Hypothesis Hopret_ok : ret_ok (Z_to_bv 64 opret).
  Hypothesis Hslo : 2 ^ 33 <= sp - (FR + NWIN).
  Hypothesis Hshi : sp <= 2 ^ 47.
  Hypothesis Hal : sp mod 16 = 0.
  Hypothesis Hds : AIMG_TOP <= ds /\ ds + 392 <= 2 ^ 47 /\ ds mod 8 = 0.
  Hypothesis DJds : ds + 392 <= sp - (FR + NWIN) \/ sp <= ds.

  #[local] Notation ssp := (sp - FR) (only parsing).
  #[local] Notation nmid := (nmid R M sp ds FR padra opret fillw SVop sv9 sv18 sv19 sv20 sv21 sv22 sv23).
  #[local] Notation nback := (nback sp ds fl lo shi FR).

  Record natop (R' R3 : bvmap 5 word) : Prop := NATOP {
    na_r2 : getr R3 2%bv = Z_to_bv 64 ssp; na_r3 : getr R3 3%bv = getr R' 3%bv; na_r4 : getr R3 4%bv = getr R' 4%bv;
    na_r10 : getr R3 10%bv = Z_to_bv 64 (ds + 8); na_r8 : getr R3 8%bv = Z_to_bv 64 ds;
    na_r9 : getr R3 9%bv = sv9; na_r18 : getr R3 18%bv = sv18; na_r19 : getr R3 19%bv = sv19; na_r20 : getr R3 20%bv = sv20;
    na_r21 : getr R3 21%bv = sv21; na_r22 : getr R3 22%bv = sv22; na_r23 : getr R3 23%bv = sv23;
    na_cs : forall r, In r [24; 25; 26; 27]%bv -> getr R3 r = getr R' r;
    na_rf : rfull R3 }.

  Lemma stage_back : forall nc R1 M1 R' M', nmid nc R1 M1 -> nback nc R1 M1 R' M' ->
    exists R3,
      HExec.msteps SEGS (@mkst (PropExec.mkFP F fc) R' (Z_to_bv 64 A_PAD_XS_RET) M' (seg_rom SEGS))
                        (@mkst (PropExec.mkFP F fc) R3 (Z_to_bv 64 opret) (wbytes M' (Z_to_bv 64 (ds + 136)) (word_to_le_bytes 8 (Z_to_bv 64 0))) (seg_rom SEGS))
      /\ natop R' R3.
